const label={full_text:'已取得全文',revise:'修正',exclude:'排除',abstract_only:'仅摘要',abstract:'仅摘要',official_record:'官方记录',official_guidance:'官方指导',guidance:'专业指导',narrative_review:'叙述性综述',professional_patient_guidance:'专业患者指导',public_health_guidance:'公共健康指导',human_study:'人体研究',original_research:'原始研究',mechanistic_study:'机制研究',partial:'覆盖不全',missing:'缺证据',covered:'已覆盖',blocked:'未通过',unknown:'待核验',unavailable:'未取得',unassessed:'待评估',frozen:'已冻结',historical:'历史版本',invalidated:'已失效',review:'分支审阅',direction:'方向选择',package:'研究包',support:'支持',counter:'反向线索',counterevidence:'反向线索',limitation:'局限',gap:'保留待补证',keep:'保留',reject:'不采用',adjust:'调整表达',primary:'主方向草案',secondary:'补充草案',supplemental:'补充草案',background:'背景资料',trial_only:'试运行草案',onset:'发生时间',duration:'持续时间',recovery:'恢复时间',progression:'变化过程',missing_reason:'尚缺信息',amplifiers:'加重因素',mitigators:'缓解因素',context:'适用场景',scope:'适用范围',claim_ids:'关联主张',source_ids:'关联来源',note:'说明',assessment:'评估说明',method:'研究方法',independence:'独立性',source_quality:'来源质量',author_fit:'作者适配性',score:'分数',status:'状态',population_limits:'人群限制',publisher_identity:'发布机构',method_basis:'方法依据',limitations:'局限',key_conclusion_eligibility:'关键结论适用性',affiliation_country:'机构所在国',study_population_countries:'研究人群地区'};
