const states=DATA.map(freshState), D=()=>DATA[active], S=()=>states[active], T=()=>C.taskFor(D(),policy), gaps=()=>D().gaps.filter(g=>g.status!=='closed'),byId=(key,id)=>(D()[key]||[]).find(x=>x.id===id);
