 const all=input.filter(x=>JSON.stringify(x).toLowerCase().includes(query)).filter(x=>tab!=='sources'||s.sourceFilter==='all'||s.sourceFilter==='pubmed'&&sourceHost(x)==='pubmed.ncbi.nlm.nih.gov'||s.sourceFilter==='mcp'&&acq.some(a=>a.source_id===x.id));
